// research: adding a second, independently sized/stopped unit to an open position is a multi-unit feature the engine does not model
isNewPullbackLow = ctx.MarketPosition() > 0 && low[0] < lowest(low, ctx.BarsSinceEntry())[1];
allowScaleInLong = isNewPullbackLow && withTrendPullbackContext[0];

// research: multiple independently priced countertrend units are a multi-unit feature the engine does not model, and 'not a strong trend day' is a context test this chapter does not reduce to a bar-level rule
madeNewChannelExtreme = high[0] >= lastScaleInPrice + minIntervalPoints;
allowScaleInShort = madeNewChannelExtreme && !strongTrendDayContext[0];

// research: requires tracking that the current position was built via a countertrend scale-in (multi-unit context not modeled) and counting qualifying adverse setups since the scale-in began
secondAdverseSetupFormed = adverseSetupCount[0] >= 2;
exitLong = ctx.MarketPosition() > 0 && wasCountertrendScaledIn[0] && secondAdverseSetupFormed;

// research: repeated partial exits require a multi-unit (or partially-closeable) position the engine does not model
nextIntervalReached = ctx.OpenPositionProfit() >= intervalsFilled[0] * intervalDollars + intervalDollars;
exitPartialLong = ctx.MarketPosition() > 0 && nextIntervalReached;

// research: adding independently-tracked with-trend units on every qualifying bar is a multi-unit position feature the engine does not model
isStrongBullTrendBar0 = close[0] > open[0] && (close[0]-open[0]) >= strongBodyFraction*(high[0]-low[0]);
allowPressLong = ctx.MarketPosition() > 0 && isStrongBullTrendBar0;

// research: the calendar test itself is a simple date comparison, but committing a fixed FRACTION OF CAPITAL on each of several scheduled entries is a capital-allocation/multi-unit feature the engine does not model
isFirstTradingDayOfMonth = Day(Date(0)) <= firstOfMonthWindow;
allowScheduledEntry = isFirstTradingDayOfMonth && scheduledEntriesRemaining[0] > 0;
